CREATE TABLE IF NOT EXISTS "user" (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, "emailVerified" boolean NOT NULL DEFAULT false, image text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "session" (id text PRIMARY KEY, "expiresAt" timestamptz NOT NULL, token text NOT NULL UNIQUE, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now(), "ipAddress" text, "userAgent" text, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS account (id text PRIMARY KEY, "accountId" text NOT NULL, "providerId" text NOT NULL, "userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, scope text, password text, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, "expiresAt" timestamptz NOT NULL, "createdAt" timestamptz DEFAULT now(), "updatedAt" timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS deletion_requests (user_id text PRIMARY KEY, state text NOT NULL DEFAULT 'pending', requested_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE IF NOT EXISTS learner_profiles (user_id text PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE, interests jsonb NOT NULL DEFAULT '[]', goal text NOT NULL DEFAULT 'Explicar um bloqueio sem roteiro', weekly_goal integer NOT NULL DEFAULT 5 CHECK(weekly_goal BETWEEN 1 AND 7), session_minutes integer NOT NULL DEFAULT 25, difficulty text NOT NULL DEFAULT 'A2', locale text NOT NULL DEFAULT 'pt-BR', timezone text NOT NULL DEFAULT 'America/Sao_Paulo', english_variant text NOT NULL DEFAULT 'en-US', theme text NOT NULL DEFAULT 'system', onboarded boolean NOT NULL DEFAULT false, diagnostic jsonb NOT NULL DEFAULT '{}', monthly_limit_cents integer NOT NULL DEFAULT 4000 CHECK(monthly_limit_cents>=0), alert_cents integer NOT NULL DEFAULT 2500 CHECK(alert_cents>=0));
CREATE TABLE IF NOT EXISTS sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, kind text NOT NULL, title text NOT NULL, author text NOT NULL, language text NOT NULL DEFAULT 'en-US', url text, video_id text, rights text NOT NULL, status text NOT NULL DEFAULT 'requested', is_example boolean NOT NULL DEFAULT false, revision integer NOT NULL DEFAULT 1, duration_ms integer, position_ms integer NOT NULL DEFAULT 0, file_key text, metadata_updated_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS source_youtube_owner ON sources(user_id,video_id) WHERE video_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS source_example_owner ON sources(user_id) WHERE is_example;
CREATE TABLE IF NOT EXISTS segments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid NOT NULL REFERENCES sources(id) ON DELETE CASCADE, ordinal integer NOT NULL, start_ms integer, end_ms integer, text text NOT NULL, translation text, origin text NOT NULL, time_accuracy text NOT NULL DEFAULT 'none', quality_status text NOT NULL DEFAULT 'user_supplied', revision integer NOT NULL DEFAULT 1, UNIQUE(source_id,ordinal), CHECK(start_ms IS NULL OR start_ms>=0), CHECK(end_ms IS NULL OR end_ms>start_ms));
CREATE TABLE IF NOT EXISTS learning_units (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid REFERENCES sources(id) ON DELETE CASCADE, user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, title text NOT NULL, objective text NOT NULL, prompt text NOT NULL, expected_answer text, kind text NOT NULL DEFAULT 'production', segment_ids jsonb NOT NULL DEFAULT '[]', vocabulary jsonb NOT NULL DEFAULT '[]', provenance text NOT NULL, schema_version text NOT NULL DEFAULT '1', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, source_id uuid REFERENCES sources(id) ON DELETE CASCADE, kind text NOT NULL, status text NOT NULL DEFAULT 'queued', completed integer NOT NULL DEFAULT 0, total integer, error_code text, error_message text, payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS job_events (id bigserial PRIMARY KEY, job_id uuid NOT NULL REFERENCES jobs(id) ON DELETE CASCADE, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS idempotency (user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, scope text NOT NULL, key text NOT NULL, fingerprint text NOT NULL, response jsonb, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,scope,key));
CREATE TABLE IF NOT EXISTS study_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, source_id uuid REFERENCES sources(id) ON DELETE SET NULL, stage text NOT NULL DEFAULT 'understand', duration_minutes integer NOT NULL DEFAULT 25, context jsonb NOT NULL DEFAULT '{}', started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_session ON study_sessions(user_id) WHERE completed_at IS NULL;
CREATE TABLE IF NOT EXISTS cards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, source_id uuid REFERENCES sources(id) ON DELETE SET NULL, segment_id uuid REFERENCES segments(id) ON DELETE SET NULL, expression text NOT NULL, normalized_expression text NOT NULL, meaning text NOT NULL, normalized_meaning text NOT NULL, example text NOT NULL, language text NOT NULL DEFAULT 'en-US', mode text NOT NULL DEFAULT 'production', fsrs_state jsonb NOT NULL, fsrs_version text NOT NULL, due timestamptz NOT NULL, version integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,language,normalized_expression,normalized_meaning,mode));
CREATE INDEX IF NOT EXISTS card_due_owner ON cards(user_id,due);
CREATE TABLE IF NOT EXISTS review_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, card_id uuid NOT NULL REFERENCES cards(id) ON DELETE CASCADE, rating integer NOT NULL CHECK(rating BETWEEN 1 AND 4), previous_state jsonb NOT NULL, next_state jsonb NOT NULL, review_log jsonb NOT NULL, version_before integer NOT NULL, undone boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS recordings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, source_id uuid REFERENCES sources(id) ON DELETE SET NULL, activity_id uuid REFERENCES learning_units(id) ON DELETE SET NULL, file_key text NOT NULL, mime_type text NOT NULL, size_bytes integer NOT NULL, duration_ms integer NOT NULL, consent_at timestamptz NOT NULL DEFAULT now(), preserve boolean NOT NULL DEFAULT false, expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, activity_id uuid REFERENCES learning_units(id) ON DELETE SET NULL, recording_id uuid REFERENCES recordings(id) ON DELETE SET NULL, kind text NOT NULL, response text NOT NULL, help_used boolean NOT NULL DEFAULT false, feedback jsonb, evaluator text NOT NULL DEFAULT 'self_recorded', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS skill_evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, attempt_id uuid REFERENCES attempts(id) ON DELETE CASCADE, skill text NOT NULL, description text NOT NULL, provenance text NOT NULL, rubric_version text NOT NULL DEFAULT '1', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS xp_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, origin_id text NOT NULL, rule text NOT NULL, amount integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,origin_id,rule));
CREATE TABLE IF NOT EXISTS budget_reservations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, period text NOT NULL, purpose text NOT NULL, amount_micros bigint NOT NULL CHECK(amount_micros>=0), state text NOT NULL DEFAULT 'active', provider_request_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS usage_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, reservation_id uuid UNIQUE REFERENCES budget_reservations(id) ON DELETE CASCADE, period text NOT NULL, purpose text NOT NULL, model text NOT NULL, input_tokens bigint NOT NULL, output_tokens bigint NOT NULL, amount_micros bigint NOT NULL, price_version text NOT NULL, raw_usage jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tutor_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, unit_id uuid REFERENCES learning_units(id) ON DELETE CASCADE, role text NOT NULL, content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS result_cache (key text PRIMARY KEY, user_id text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, value jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rate_limits (key text PRIMARY KEY, count integer NOT NULL, resets_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS evidence_owner_time ON skill_evidence(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS sources_owner ON sources(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS usage_owner_period ON usage_events(user_id,period);
